interface ProductsUpdateEvent extends CustomEvent {
  detail: {
    sections: {
      [key: string]: string;
    };
  };
}

class ProductCount extends HTMLElement {
  private unsubscribe: (() => void) | undefined;

  constructor() {
    super();
  }

  connectedCallback(): void {
    const sectionId = this.getAttribute("data-section-id");

    if (!sectionId) {
      return;
    }

    this.unsubscribe = this.handleEvent<ProductsUpdateEvent>(
      "products:update",
      (event) => {
        const section = event.detail.sections[sectionId];

        if (!section) {
          return;
        }

        const newHtml = new DOMParser().parseFromString(section, "text/html");
        const newResults = newHtml.querySelector<HTMLElement>(
          this.tagName.toLowerCase(),
        );

        if (!newResults) {
          return;
        }

        this.replaceWith(newResults);
      },
    );
  }

  private handleEvent<T extends Event>(
    eventName: string,
    handler: (event: T) => void,
  ): () => void {
    const boundHandler = (event: Event) => handler(event as T);
    document.addEventListener(eventName, boundHandler);
    return () => document.removeEventListener(eventName, boundHandler);
  }

  disconnectedCallback(): void {
    this.unsubscribe?.();
  }
}

customElements.define("uwp-product-count", ProductCount);
